## Dependencies and Configuration

```xml
<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-oauth2-client</artifactId>
</dependency>
```

```yaml
# application.yml
spring:
  security:
    oauth2:
      client:
        registration:
          google:
            client-id: ${GOOGLE_CLIENT_ID}
            client-secret: ${GOOGLE_CLIENT_SECRET}
            scope: openid, email, profile
            redirect-uri: "{baseUrl}/oauth2/callback/{registrationId}"
          github:
            client-id: ${GITHUB_CLIENT_ID}
            client-secret: ${GITHUB_CLIENT_SECRET}
            scope: read:user, user:email
        provider:
          google:
            # Auto-configured for common providers
          github:
            # Auto-configured
```

## Custom OAuth2UserService

```java
@Service
public class CustomOAuth2UserService extends DefaultOAuth2UserService {

    @Autowired
    private UserRepository userRepo;

    @Override
    public OAuth2User loadUser(OAuth2UserRequest userRequest) throws OAuth2AuthenticationException {
        OAuth2User oauth2User = super.loadUser(userRequest);  // Fetches user from provider

        String provider = userRequest.getClientRegistration().getRegistrationId();  // "google", "github"
        String providerId = oauth2User.getName();  // Provider's user ID
        String email = oauth2User.getAttribute("email");
        String name = oauth2User.getAttribute("name");

        // Find or create user in your DB
        User user = userRepo.findByEmail(email).orElseGet(() -> {
            User newUser = new User();
            newUser.setEmail(email);
            newUser.setName(name);
            newUser.setProvider(provider);
            newUser.setProviderId(providerId);
            newUser.setRole(Role.USER);
            return userRepo.save(newUser);
        });

        return UserPrincipal.create(user, oauth2User.getAttributes());
    }
}

// UserPrincipal wraps your User + OAuth2User:
public class UserPrincipal implements OAuth2User, UserDetails {
    private final User user;
    private final Map<String, Object> attributes;

    @Override
    public Map<String, Object> getAttributes() { return attributes; }
    @Override
    public String getName() { return user.getEmail(); }
    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return List.of(new SimpleGrantedAuthority("ROLE_" + user.getRole().name()));
    }
    public Long getUserId() { return user.getId(); }
}
```

## OAuth2 Success Handler — Issue JWT

```java
@Component
public class OAuth2AuthenticationSuccessHandler extends SimpleUrlAuthenticationSuccessHandler {

    @Autowired
    private JwtUtil jwtUtil;

    @Value("${app.frontend-url}")
    private String frontendUrl;

    @Override
    public void onAuthenticationSuccess(HttpServletRequest request,
                                         HttpServletResponse response,
                                         Authentication authentication) throws IOException {
        UserPrincipal principal = (UserPrincipal) authentication.getPrincipal();

        // Generate JWT for the authenticated user
        String token = jwtUtil.generateToken(principal);

        // Redirect to frontend with token
        // Option 1: Token in URL fragment (not logged by servers)
        String redirectUrl = frontendUrl + "/oauth2/success#token=" + token;

        // Option 2: Store in temp Redis key, redirect with one-time code
        // String code = UUID.randomUUID().toString();
        // redis.opsForValue().set("oauth2:code:" + code, token, Duration.ofMinutes(5));
        // redirectUrl = frontendUrl + "/oauth2/callback?code=" + code;

        getRedirectStrategy().sendRedirect(request, response, redirectUrl);
    }
}

@Component
public class OAuth2AuthenticationFailureHandler extends SimpleUrlAuthenticationFailureHandler {
    @Override
    public void onAuthenticationFailure(HttpServletRequest request,
                                         HttpServletResponse response,
                                         AuthenticationException exception) throws IOException {
        String redirectUrl = frontendUrl + "/login?error=oauth2_failure";
        getRedirectStrategy().sendRedirect(request, response, redirectUrl);
    }
}
```

## Security Configuration

```java
@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http
        .csrf(csrf -> csrf.disable())
        .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .oauth2Login(oauth2 -> oauth2
            .authorizationEndpoint(auth -> auth
                .baseUri("/oauth2/authorize")
            )
            .redirectionEndpoint(redirect -> redirect
                .baseUri("/oauth2/callback/*")
            )
            .userInfoEndpoint(info -> info
                .userService(customOAuth2UserService)
            )
            .successHandler(oAuth2SuccessHandler)
            .failureHandler(oAuth2FailureHandler)
        )
        .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
    return http.build();
}
```

## Production Reality

Don't pass the JWT token directly in the URL for production — it gets logged in access logs and referrer headers. Use the one-time code approach: store the token in Redis with a 5-minute TTL keyed by a UUID, redirect with the UUID, frontend calls a `/oauth2/token?code=UUID` endpoint to retrieve the JWT. This keeps tokens out of logs.

## JWT Resource Server

```xml
<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-oauth2-resource-server</artifactId>
</dependency>
```

```yaml
# application.yml
spring:
  security:
    oauth2:
      resourceserver:
        jwt:
          # Option 1: Auto-discover JWKS from issuer
          issuer-uri: https://your-auth-server.com
          # Spring fetches: https://your-auth-server.com/.well-known/openid-configuration
          # Then fetches JWKS from: ...jwks_uri

          # Option 2: Direct JWKS URI
          # jwk-set-uri: https://your-auth-server.com/.well-known/jwks.json
```

```java
@Configuration
@EnableWebSecurity
public class ResourceServerConfig {

    @Bean
    public SecurityFilterChain resourceServerFilterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(jwt -> jwt
                    .jwtAuthenticationConverter(jwtAuthenticationConverter())
                )
            );
        return http.build();
    }

    @Bean
    public JwtAuthenticationConverter jwtAuthenticationConverter() {
        JwtGrantedAuthoritiesConverter grantedAuthoritiesConverter =
            new JwtGrantedAuthoritiesConverter();

        // Map 'roles' JWT claim to Spring GrantedAuthority
        grantedAuthoritiesConverter.setAuthoritiesClaimName("roles");
        grantedAuthoritiesConverter.setAuthorityPrefix("ROLE_");  // Or "" if already prefixed

        JwtAuthenticationConverter converter = new JwtAuthenticationConverter();
        converter.setJwtGrantedAuthoritiesConverter(grantedAuthoritiesConverter);
        return converter;
    }
}
```

## Accessing JWT Claims in Controllers

```java
@RestController
@RequestMapping("/api/orders")
public class OrderController {

    // Via @AuthenticationPrincipal:
    @GetMapping
    public List<Order> getMyOrders(@AuthenticationPrincipal Jwt jwt) {
        String userId = jwt.getSubject();
        String email = jwt.getClaimAsString("email");
        List<String> roles = jwt.getClaimAsStringList("roles");

        return orderRepo.findByUserId(Long.parseLong(userId));
    }

    // Via SecurityContextHolder:
    @GetMapping("/me")
    public Map<String, Object> getMyInfo() {
        JwtAuthenticationToken auth =
            (JwtAuthenticationToken) SecurityContextHolder.getContext().getAuthentication();
        Jwt jwt = auth.getToken();
        return Map.of(
            "userId", jwt.getSubject(),
            "email", jwt.getClaimAsString("email"),
            "scopes", jwt.getClaimAsStringList("scp")
        );
    }
}
```

## Opaque Token Introspection

```yaml
# For opaque tokens:
spring:
  security:
    oauth2:
      resourceserver:
        opaquetoken:
          introspection-uri: https://your-auth-server.com/oauth2/introspect
          client-id: resource-server-client-id
          client-secret: resource-server-secret
```

```java
// Configure opaque token support:
http.oauth2ResourceServer(oauth2 -> oauth2
    .opaqueToken(opaque -> opaque
        .introspectionUri("https://auth-server/introspect")
        .introspectionClientCredentials("client-id", "client-secret")
    )
);

// Each request: POST to introspection endpoint, verify token is active
// Response includes: username, scopes, expiry
// Slower than JWT but instantly revocable
```

## Microservice Token Forwarding

```java
// Service A receives JWT, calls Service B — forwards the token
@Bean
public WebClient webClient(OAuth2AuthorizedClientManager authorizedClientManager) {
    ServletOAuth2AuthorizedClientExchangeFilterFunction oauth2 =
        new ServletOAuth2AuthorizedClientExchangeFilterFunction(authorizedClientManager);
    return WebClient.builder().apply(oauth2.oauth2Configuration()).build();
}

// Or manually forward the token:
@GetMapping("/api/orders")
public List<Order> getOrders(@RequestHeader("Authorization") String authHeader) {
    return webClient.get()
        .uri("http://order-service/api/orders")
        .header("Authorization", authHeader)  // Forward token to downstream service
        .retrieve()
        .bodyToFlux(Order.class)
        .collectList()
        .block();
}
```

## Production Reality

For internal microservices using your own auth server: JWT resource server with JWKS auto-discovery is the standard. Each service validates tokens locally — no per-request auth server calls. For third-party tokens (Stripe, AWS, external partners): always verify issuer and intended audience (`aud` claim) — don't accept tokens meant for another service. Configure `required-claims: aud: [your-service-id]` to prevent audience confusion attacks.

## OAuth2 vs OIDC

```
OAuth2 Authorization Code Flow:
  Scope: read:photos
  Returns: access_token
  Purpose: "Allow app to read my photos"
  Access token: used to call API (opaque to the app)

OIDC Authorization Code Flow:
  Scope: openid email profile
  Returns: access_token + id_token + (optionally) refresh_token
  Purpose: "Allow app to know who I am AND access my photos"
  id_token: JWT with user identity claims
  access_token: used to call UserInfo endpoint
```

## id_token Structure

```json
{
  "iss": "https://accounts.google.com",   // Issuer
  "sub": "110169484474386276334",           // Subject (unique user ID at this provider)
  "aud": "your-client-id",                 // Audience (must be your client ID)
  "exp": 1700003600,                        // Expiration
  "iat": 1700000000,                        // Issued at
  "auth_time": 1700000000,                  // When user authenticated
  "email": "user@gmail.com",
  "email_verified": true,
  "name": "John Doe",
  "picture": "https://...",
  "locale": "en"
}
```

## OIDC Validation Requirements

```java
// id_token validation — more strict than regular JWT:
// 1. Signature valid (same as JWT)
// 2. iss = expected issuer
// 3. aud contains your client_id
// 4. exp in future
// 5. iat not too far in the past (usually within 5 min)
// 6. nonce matches if provided in request (prevents replay attacks)

// Spring's OidcIdTokenValidator handles all of this:
// When using spring-security-oauth2-client, validation is automatic

// Manual validation with Nimbus SDK:
OIDCIdToken idToken = OIDCIdToken.parse(signedJWT);
IDTokenValidator validator = new IDTokenValidator(issuerURI, clientID);
IDTokenClaimsSet claims = validator.validate(idToken, nonce);
// Throws if invalid
```

## OIDC Discovery

```
https://accounts.google.com/.well-known/openid-configuration
{
  "issuer": "https://accounts.google.com",
  "authorization_endpoint": "https://accounts.google.com/o/oauth2/v2/auth",
  "token_endpoint": "https://oauth2.googleapis.com/token",
  "userinfo_endpoint": "https://openidconnect.googleapis.com/v1/userinfo",
  "jwks_uri": "https://www.googleapis.com/oauth2/v3/certs",
  "scopes_supported": ["openid", "email", "profile", ...],
  "response_types_supported": ["code", ...],
  "subject_types_supported": ["public"],
  "id_token_signing_alg_values_supported": ["RS256"]
}

// Spring Security uses this for auto-configuration:
// spring.security.oauth2.client.provider.google.issuer-uri=https://accounts.google.com
// Spring fetches the discovery document and configures all endpoints
```

## Using OIDC in Spring Security (Custom OAuth2UserService → OIDC)

```java
// For OIDC providers, use OidcUserService instead of OAuth2UserService:
@Service
public class CustomOidcUserService extends OidcUserService {

    @Override
    public OidcUser loadUser(OidcUserRequest userRequest) throws OAuth2AuthenticationException {
        OidcUser oidcUser = super.loadUser(userRequest);

        OidcIdToken idToken = oidcUser.getIdToken();
        String sub = idToken.getSubject();        // Unique, stable user ID at provider
        String email = idToken.getEmail();
        String name = idToken.getFullName();

        // Find or create in your DB
        User user = findOrCreateUser(sub, email, name, "google");

        return new DefaultOidcUser(
            AuthorityUtils.createAuthorityList("ROLE_USER"),
            oidcUser.getIdToken(),
            oidcUser.getUserInfo()
        );
    }
}

// In SecurityConfig:
http.oauth2Login(oauth2 -> oauth2
    .userInfoEndpoint(info -> info
        .oidcUserService(customOidcUserService)  // Use for OIDC providers
        .userService(customOAuth2UserService)     // Use for non-OIDC (GitHub)
    )
);
```

## Production Reality

Always use `sub` (subject) from the id_token as the primary identifier for the user in your system — not email. Email can change; `sub` is stable and unique per provider per user. Store `{provider, sub}` as the foreign key for OAuth2-authenticated users. This also correctly handles users who sign in with multiple providers.
